def schedule_overlap(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
    out = []
    for s1, e1 in a:                         # every pair of ranges
        for s2, e2 in b:
            lo, hi = max(s1, s2), min(e1, e2)
            if lo <= hi:
                out.append([lo, hi])
    return sorted(out)
